message.content:
{
  "title": "Rescue Through the Ruined City",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver finds the first clue on a shattered mirror.",
      "visual_description": "A ruined courtyard with a cracked mirror leaning against a broken wall, reflecting the sky. The glass diver kneels, examining a shattered piece that glows faintly.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the cartographer traces the path on an old map.",
      "visual_description": "Mara unfurls a stained parchment map under a flickering lantern, her brass compass pointing toward the ruined castle gates in the distance.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of the cursed tower ahead.",
      "visual_description": "The oracle lamp sits on a stone ledge, its single eye flickering as it casts a shadow of a twisted spire on the wall behind.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The sleeping tax collector dozes near the castle gates.",
      "visual_description": "A massive iron gate stands ajar, and the sleeping tax collector slumps against it, using a ledger as a pillow, papers scattered on the ground.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "The tin fox scouts ahead through a collapsed archway.",
      "visual_description": "The small metal fox creeps through rubble under a crumbling arch, its blue glass eyes scanning for danger, key-wind tail ticking softly.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Mara and the glass diver meet at the old royal banner.",
      "visual_description": "A tattered royal banner hangs from a broken pole above a cobblestone square, and Mara points to it while the glass diver adjusts his helmet.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "The oracle lamp reveals a hidden stair beneath a well.",
      "visual_description": "The lamp's flame illuminates a rusty grate at the bottom of a dry well, revealing stone steps descending into darkness.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The tin fox triggers a trap but dodges a falling portcullis.",
      "visual_description": "A portcullis crashes down where the tin fox stood moments before, its tail winding faster as it skitters to safety.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The glass diver swims through a window into a locked chamber.",
      "visual_description": "The glass diver presses his helmet against a stained glass window, his form dissolving into the reflection and emerging inside a dusty room.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Mara paints a new passage on her map to bypass a sealed door.",
      "visual_description": "Mara dips her brush in ink and draws a line on the map; the real wall before her shimmers and reveals a narrow corridor.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "The sleeping tax collector is carried by the tin fox after a stampede.",
      "visual_description": "The tin fox drags the still-sleeping tax collector by his coat collar, ledger papers trailing, as dust clouds rise behind them.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The oracle lamp guides the group through a maze of mirrors.",
      "visual_description": "The lamp floats ahead, its reflection multiplying in a hall of mirrors, each flame-eye pointing left or right.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "A magic door only opens when the glass diver removes his helmet.",
      "visual_description": "A door carved with waves stands before the glass diver; he lifts his helmet and his reflection on the door's surface smiles and swings open.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Mara recognizes the tower's curse in a fading mural.",
      "visual_description": "A circular room with faded frescos of a coiled serpent; Mara touches a painted eye and the floor trembles.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "The tin fox winds itself up to carry a key from a high ledge.",
      "visual_description": "The metal fox climbs a crumbling pillar, its key-wind tail spinning as it leaps to grab a rusted key from a niche.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The sleeping tax collector sleepwalks and unlocks a chain.",
      "visual_description": "Still asleep, the tax collector shuffles to a heavy chain, pulls a stamped paper from his sleeve, and the chain falls away.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The oracle lamp warns of the bridge's false planks.",
      "visual_description": "At the edge of a long stone bridge over a chasm, the lamp's eye glows red, pointing at several cracked flagstones.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "All five cross the bridge as the city collapses behind them.",
      "visual_description": "The glass diver, Mara, the oracle lamp, the sleeping tax collector (carried by the tin fox), race across the bridge; the ruined city crumbles in the background under a red sky.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ]
}

